def maximum_partition_sum(arr, k):
 dp=[0]*(len(arr)+1)
 for end in range(1,len(arr)+1):
  largest=0
  for size in range(1,min(k,end)+1):largest=max(largest,arr[end-size]);dp[end]=max(dp[end],dp[end-size]+largest*size)
 return dp[-1]

